.nb-scope {

  --field: #050507;
  --obsidian: #0B0D12;
  --raise: #10141d;
  --card: #141a28;
  --deep: #0a0e16;


  --white: #F8F7FB;
  --ink: #F5F7FB;
  --quiet: rgba(248,247,251,.72);
  --secondary: rgba(248,247,251,.55);
  --line: rgba(255,255,255,.12);


  --soul: #a06bff;


  --magenta: #e84fff;  
  --purple: #a06bff;   
  --blue: #3fb8ff;     
  --green: #2fe89e;    
  --gold: #ffbf3d;     


  --magenta-rgb: 232,79,255;
  --purple-rgb: 160,107,255;
  --blue-rgb: 63,184,255;
  --green-rgb: 47,232,158;
  --gold-rgb: 255,191,61;


  --teal: #40d3bb;
  --teal-rgb: 64,211,187;
  --coral: #ff5e6c;
  --coral-rgb: 255,94,108;
  --lime: #b8ee57;
  --lime-rgb: 184,238,87;
  --indigo: #6675ff;
  --indigo-rgb: 102,117,255;


  --verified: #2fe89e;
  --verified-rgb: 47,232,158;
  --claim: #ffbf3d;
  --claim-rgb: 255,191,61;
  --demo: #e84fff;
  --demo-rgb: 232,79,255;


  --ease: cubic-bezier(.22,1,.36,1);
  --snap: cubic-bezier(.32,.72,0,1);


  --lift: 0 18px 50px rgba(0,0,0,.55), 0 6px 18px rgba(0,0,0,.4);
  --ring: 0 0 0 2px rgba(160,107,255,.35);


  --r-sm: 11px;
  --r-md: 13px;
  --r-lg: 18px;
  --r-xl: 26px;
  --r-pill: 999px;


  --type-display: 64px;
  --type-chapter: 40px;
  --type-headline: 24px;
  --type-body: 18px;
  --type-small: 14px;
}
.nb-scope .living-btn {
  position: relative; overflow: hidden; cursor: pointer; border: none;
  font-family: Inter, sans-serif; font-weight: 800; font-size: 17px; letter-spacing: .12em;
  color: #fff; padding: 22px 44px; border-radius: 999px; min-width: 300px;
  background: linear-gradient(180deg, #17171c 0%, #050505 55%, #0a0a0e 100%);
  box-shadow:
    inset 0 0 0 1.7px rgba(255,255,255,.92),
    inset 0 2px 6px rgba(255,255,255,.22),
    inset 0 -8px 18px rgba(0,0,0,.75),
    0 14px 40px rgba(0,0,0,.6),
    0 4px 14px rgba(0,0,0,.5);
  transition: transform .28s var(--ease), box-shadow .28s var(--ease);
  animation: idleBreathe 4.2s ease-in-out infinite;
}
.nb-scope .living-btn .btn-glow { position: absolute; inset: -2px; border-radius: 999px; opacity: .55; pointer-events: none; transition: opacity .3s; }
.nb-scope .living-btn[data-spectrum="magenta"] .btn-glow { box-shadow: 0 0 34px 4px rgba(232,79,255,.5), inset 0 0 22px rgba(232,79,255,.28); }
.nb-scope .living-btn[data-spectrum="purple"] .btn-glow { box-shadow: 0 0 34px 4px rgba(160,107,255,.5), inset 0 0 22px rgba(160,107,255,.28); animation-delay: 1.4s; }
.nb-scope .living-btn[data-spectrum="blue"] .btn-glow { box-shadow: 0 0 34px 4px rgba(63,184,255,.5), inset 0 0 22px rgba(63,184,255,.28); animation-delay: 2.8s; }
.nb-scope .living-btn::after {
  content: ""; position: absolute; top: -20%; bottom: -20%; width: 46%; left: -70%;
  background: linear-gradient(105deg, transparent 20%, rgba(255,255,255,.34) 50%, transparent 80%);
  transform: skewX(-18deg); pointer-events: none;
  animation: sweep 5.5s var(--ease) infinite;
}
.nb-scope .living-btn[data-spectrum="purple"]::after { animation-delay: 1.8s; }
.nb-scope .living-btn[data-spectrum="blue"]::after { animation-delay: 3.6s; }
@keyframes sweep { 0%, 62% { left: -70%; } 88%, 100% { left: 130%; } }
@keyframes idleBreathe {
  0%, 100% { box-shadow: inset 0 0 0 1.7px rgba(255,255,255,.92), inset 0 2px 6px rgba(255,255,255,.22), inset 0 -8px 18px rgba(0,0,0,.75), 0 14px 40px rgba(0,0,0,.6), 0 4px 14px rgba(0,0,0,.5); }
  50% { box-shadow: inset 0 0 0 1.7px rgba(255,255,255,1), inset 0 2px 8px rgba(255,255,255,.3), inset 0 -8px 18px rgba(0,0,0,.75), 0 18px 52px rgba(0,0,0,.65), 0 4px 14px rgba(0,0,0,.5); }
}
.nb-scope .living-btn:hover { transform: translateY(-4px) scale(1.025); animation: none; }
.nb-scope .living-btn[data-spectrum="magenta"]:hover { box-shadow: inset 0 0 0 2px var(--magenta), inset 0 2px 8px rgba(255,255,255,.3), inset 0 -8px 18px rgba(0,0,0,.7), 0 22px 60px rgba(232,79,255,.4), 0 6px 18px rgba(0,0,0,.5); }
.nb-scope .living-btn[data-spectrum="purple"]:hover { box-shadow: inset 0 0 0 2px var(--purple), inset 0 2px 8px rgba(255,255,255,.3), inset 0 -8px 18px rgba(0,0,0,.7), 0 22px 60px rgba(160,107,255,.4), 0 6px 18px rgba(0,0,0,.5); }
.nb-scope .living-btn[data-spectrum="blue"]:hover { box-shadow: inset 0 0 0 2px var(--blue), inset 0 2px 8px rgba(255,255,255,.3), inset 0 -8px 18px rgba(0,0,0,.7), 0 22px 60px rgba(63,184,255,.4), 0 6px 18px rgba(0,0,0,.5); }
.nb-scope .living-btn:hover .btn-glow { opacity: 1; }
.nb-scope .living-btn:active { transform: translateY(1px) scale(.975); transition-duration: .08s; }
.nb-scope .living-btn .btn-label { position: relative; z-index: 2; display: flex; align-items: center; justify-content: center; gap: 12px; }
.nb-scope .living-btn .btn-label svg { width: 20px; height: 20px; }
@media (max-width: 860px) {.nb-scope .living-btn { min-width: 100%; }}
@media (prefers-reduced-motion: reduce) {.nb-scope .living-btn, .nb-scope .living-btn::after { animation: none; }}

