  50% { box-shadow:
    inset 0 0 0 1px rgba(240,238,230,.46),
    inset 0 1px 0 rgba(255,255,255,.52),
    inset 0 -1px 0 rgba(0,0,0,.75),
    inset 0 -16px 30px rgba(0,0,0,.55),
    inset 0 12px 22px rgba(255,255,255,.08),
