    linear-gradient(180deg, rgba(255,255,255,.16) 0%, rgba(255,255,255,.04) 38%, rgba(0,0,0,.18) 100%),
    linear-gradient(180deg, #2e2e38 0%, #101016 52%, #060608 100%);
  box-shadow:
    inset 0 0 0 1px rgba(240,238,230,.72),
