.nb-scope .lv-btn:active {
  transform: translateY(1px) scale(.97) !important;
  transition-duration: .08s;
  box-shadow:
    inset 0 0 0 1px rgba(240,238,230,.48),
    inset 0 4px 14px rgba(0,0,0,.85),
    inset 0 -4px 10px rgba(0,0,0,.55),
    inset 0 12px 22px rgba(0,0,0,.30),
    0 10px 24px rgba(0,0,0,.78);
