  box-shadow:inset 0 0 0 1px rgba(20,21,26,.48), inset 0 1px 0 rgba(255,255,255,1), inset 0 -1px 0 rgba(20,21,26,.32), inset 0 -14px 24px rgba(20,21,26,.14), inset 0 10px 18px rgba(255,255,255,.55), 0 0 22px -4px rgba(138,92,255,.50), 0 34px 64px rgba(0,0,0,.88), 0 10px 22px rgba(0,0,0,.62);
}
.nb-scope .naya-btn.naya-btn--foundation-light[aria-pressed="true"] {
  box-shadow:inset 0 0 0 1px rgba(20,21,26,.50), inset 0 1px 0 rgba(255,255,255,1), inset 0 -1px 0 rgba(20,21,26,.34), inset 0 -14px 24px rgba(20,21,26,.15), inset 0 10px 18px rgba(255,255,255,.55), 0 0 0 1.5px rgba(138,92,255,.9), 0 0 30px -10px rgba(138,92,255,.55), 0 28px 54px rgba(0,0,0,.86), 0 8px 18px rgba(0,0,0,.60);
}
.nb-scope .naya-btn.naya-btn--foundation-soul {
  --nb-accent:#ffd45a; --nb-accent-rgb:255,212,90; --nb-jewel:#8a5cff;
  background:linear-gradient(180deg, rgba(255,255,255,.16), rgba(255,255,255,.02) 42%, rgba(0,0,0,.22)), linear-gradient(180deg,#9d7fff 0%,#6a3df2 46%,#240a63 100%);
}
