.nb-scope {
  color-scheme:light dark;
  --field:#07070a;--surface:#101116;--surface-2:#17181f;--ink:#f8f7fb;--quiet:#c8c2ce;
  --line:rgba(255,255,255,.20);--soft-line:rgba(255,255,255,.10);--chrome:#08080b;
  --magenta:#e455f4;--purple:#8d63f5;--blue:#3f9ff5;--cyan:#39d7e8;--green:#34d38a;--gold:#e7c65a;
  --mat-0:#020203;--mat-1:#08080b;--mat-2:#101117;--mat-3:#1b1c24;--mat-white:#fbfaff;
  --ease:cubic-bezier(.16,.84,.22,1);--snap:cubic-bezier(.2,.8,.2,1);
  --shadow:0 26px 70px rgba(28,18,38,.18),0 7px 22px rgba(28,18,38,.11);
  --page:clamp(17px,4vw,68px);--radius:24px;
}
.nb-scope .icon {width:20px;height:20px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
@keyframes ring-spin {to{transform:rotate(360deg)}}
.nb-scope .n-btn .btn-orb .icon {width:15px;height:15px;filter:drop-shadow(0 1px 2px rgba(0,0,0,.6))}
.nb-scope .n-btn.prism .prism-mark .icon {width:14px;height:14px;transform:rotate(-45deg)}
.nb-scope .n-btn.split {padding:0 6px 0 24px;gap:18px}
.nb-scope .n-btn.split .split-orb {width:44px;height:44px;border-radius:50%;display:grid;place-items:center;border:1px solid rgba(255,255,255,.75);background:radial-gradient(circle at 35% 28%,rgba(255,255,255,.8),rgba(var(--rgb),.35) 25%,#050506 72%);box-shadow:inset 0 -7px 12px rgba(0,0,0,.65)}
.nb-scope .jewel .icon {transform:rotate(7deg);filter:drop-shadow(0 0 7px #fff)}
.nb-scope .sphere .icon {width:26px;height:26px;color:#fff;filter:drop-shadow(0 0 8px rgba(255,255,255,.6))}
.nb-scope .mini-gem .icon {width:18px;height:18px}
.nb-scope .mini-gem.diamond .icon {transform:rotate(-45deg)}
.nb-scope .naya-btn {--tone:#8d63f5;position:relative;isolation:isolate;display:inline-flex;align-items:center;justify-content:center;gap:10px;min-height:54px;padding:12px 24px;border-radius:999px;font-size:14px;font-weight:800;letter-spacing:.06em;cursor:pointer;font-family:inherit;color:#fff;background:linear-gradient(180deg,#15151a,#050506);border:1.5px solid rgba(255,255,255,.78);box-shadow:inset 0 2px 2px rgba(255,255,255,.22),inset 0 -3px 6px rgba(0,0,0,.6),0 0 22px -2px rgba(255,255,255,.18),0 12px 28px rgba(0,0,0,.65);transition:border-color .22s var(--ease),box-shadow .22s var(--ease),transform .22s var(--ease),color .22s var(--ease);-webkit-tap-highlight-color:transparent}
.nb-scope .naya-btn>* {position:relative;z-index:2}
.nb-scope .naya-btn:before {content:"";position:absolute;z-index:1;inset:-2px;border-radius:inherit;padding:1px;background:conic-gradient(from 0deg,transparent 0 210deg,rgba(141,99,245,.08) 224deg,rgba(141,99,245,.34) 255deg,rgba(255,255,255,.28) 270deg,transparent 302deg);opacity:0;pointer-events:none;mask:linear-gradient(#000 0 0) content-box,linear-gradient(#000 0 0);mask-composite:exclude}
.nb-scope .naya-btn:hover, .nb-scope .naya-btn:focus-visible, .nb-scope .naya-btn.forced-hover {border-color:var(--purple);transform:translateY(-2px);box-shadow:inset 0 2px 2px rgba(255,255,255,.25),inset 0 -3px 6px rgba(0,0,0,.5),0 0 14px -4px var(--purple),0 16px 34px rgba(0,0,0,.68)}
.nb-scope .naya-btn:hover:before, .nb-scope .naya-btn:focus-visible:before, .nb-scope .naya-btn.forced-hover:before {opacity:1;animation:ring-spin 2.8s linear infinite}
.nb-scope .naya-btn:focus-visible {outline:2px solid #fff;outline-offset:4px}
.nb-scope .naya-btn:active, .nb-scope .naya-btn.forced-active {transform:translateY(1px) scale(.98);box-shadow:inset 0 3px 8px rgba(0,0,0,.7),0 6px 13px rgba(0,0,0,.65);border-color:var(--purple)}
.nb-scope .naya-btn:disabled {opacity:.38;filter:saturate(.1);cursor:not-allowed;transform:none;border-color:rgba(255,255,255,.35);box-shadow:inset 0 1px rgba(255,255,255,.1),0 6px 14px rgba(0,0,0,.42)}
.nb-scope .naya-btn.machine {background:linear-gradient(145deg,#101016,#050505 56%,#0b0b10);border:1.5px solid rgba(255,255,255,.9);padding:12px 24px;font-size:16px;font-weight:600;box-shadow:inset 0 1px 0 rgba(255,255,255,.14),0 8px 20px rgba(0,0,0,.55)}
.nb-scope .naya-btn.machine:hover, .nb-scope .naya-btn.machine:focus-visible {border-color:var(--purple);box-shadow:inset 0 1px 0 rgba(255,255,255,.14),0 0 14px -3px var(--purple),0 12px 24px rgba(0,0,0,.62)}
.nb-scope .naya-btn.lead {min-height:58px;padding:15px 32px}
.nb-scope .naya-btn.streak:after {content:"";position:absolute;inset:2px 22px auto;height:1px;background:linear-gradient(90deg,transparent,rgba(255,255,255,.7),transparent)}
.nb-scope .naya-btn.proximity {background:radial-gradient(170px circle at var(--px,50%) var(--py,20%),rgba(255,255,255,.12),transparent 48%),linear-gradient(180deg,#15151b 0%,#020203 58%,#000 100%)}
.nb-scope .naya-btn.small {min-height:44px;padding:8px 17px}
.nb-scope .naya-btn.compact {min-height:42px;padding:8px 14px;border-radius:12px;font-size:12px}
.nb-scope .naya-btn.icon {width:58px;height:58px;min-height:58px;padding:0;border-radius:50%;letter-spacing:0}
.nb-scope .naya-btn.icon:before {inset:-5px}
.nb-scope .naya-btn.icon.micro {width:44px;height:44px;min-height:44px}
.nb-scope .naya-btn.icon.portal {width:66px;height:66px;border-color:#fff;box-shadow:inset 0 2px 3px rgba(255,255,255,.24),inset 0 -10px 16px rgba(0,0,0,.75),0 5px 0 #010102,0 18px 30px rgba(0,0,0,.72)}
.nb-scope .naya-btn.icon.portal .icon {fill:#fff}
.nb-scope .naya-btn.split {padding-right:6px}
.nb-scope .naya-btn.split .split-orb {position:relative;z-index:2;width:44px;height:44px;border-radius:50%;display:grid;place-items:center;border:1px solid rgba(255,255,255,.75);background:radial-gradient(circle at 35% 28%,rgba(255,255,255,.8),rgba(141,99,245,.25) 25%,#050506 72%)}
.nb-scope .naya-btn .btn-orb {position:relative;width:30px;height:30px;display:grid;place-items:center;border-radius:50%;background:radial-gradient(circle at 34% 24%,rgba(255,255,255,.92),var(--tone) 35%,#060609 80%);border:1px solid rgba(255,255,255,.8);box-shadow:inset 0 -5px 9px rgba(0,0,0,.6),0 0 9px -2px var(--tone)}
.nb-scope .naya-btn.prism {border-radius:17px}
.nb-scope .naya-btn.prism .prism-mark {position:relative;width:26px;height:26px;display:grid;place-items:center;transform:rotate(45deg);border:1px solid rgba(255,255,255,.8);background:linear-gradient(135deg,#fff,var(--tone) 34%,#170d25 68%,#050507);box-shadow:inset 0 1px rgba(255,255,255,.5),0 0 10px -2px var(--tone)}
.nb-scope .naya-btn.prism .prism-mark .icon {transform:rotate(-45deg)}
.nb-scope .bad-action .icon {width:20px;height:20px}
.nb-scope .toast-mini>.icon {color:var(--tone)}
.nb-scope .smart-link>.icon {color:var(--tone);flex:none}
.nb-scope .share-actions .naya-btn {flex:1;padding-inline:10px}
@media(max-width:620px) {.nb-scope .media-player>.naya-btn:last-child {grid-column:1/-1;width:100%;border-radius:13px}
.nb-scope .share-actions .naya-btn {width:100%}}

