    radial-gradient(circle at 50% 62%, rgba(255,255,255,.10) 0%, transparent 42%),
    radial-gradient(circle at 50% 50%, var(--oc) 0%, color-mix(in srgb, var(--oc) 62%, #000) 56%, #040406 100%);
  box-shadow:
    inset 0 0 0 1.5px rgba(255,255,255,.50),
    inset 0 10px 18px rgba(255,255,255,.14),
    inset 0 -12px 24px rgba(0,0,0,.62),
    0 0 30px rgba(var(--oc-rgb),.55),
    0 0 74px -10px rgba(var(--oc-rgb),.42),
    0 24px 48px rgba(0,0,0,.65);
  transition: transform .32s var(--ease), box-shadow .32s var(--ease);
  animation: orb-breathe 5s ease-in-out infinite;
}
.nb-scope .orb-wrap:nth-child(2) .orb { animation-delay: 1s; }
.nb-scope .orb-wrap:nth-child(3) .orb { animation-delay: 2s; }
.nb-scope .orb-wrap:nth-child(4) .orb { animation-delay: 3s; }
.nb-scope .orb-wrap:nth-child(5) .orb { animation-delay: 4s; }
@keyframes orb-breathe { 0%,100% { transform: scale(1); } 50% { transform: scale(1.045); } }
.nb-scope .orb::before { content: ""; position: absolute; inset: -17px; border-radius: 50%;
  background: conic-gradient(from 0deg, transparent 0deg, transparent 282deg, rgba(var(--oc-rgb),.85) 328deg, rgba(255,255,255,.95) 350deg, transparent 360deg);
  -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
  -webkit-mask-composite: xor; mask-composite: exclude; padding: 3px;
  animation: orb-spin 6s linear infinite; opacity: .85; pointer-events: none;
}
.nb-scope .orb::after { content: ""; position: absolute; left: 16%; right: 16%; bottom: -30px; height: 24px; border-radius: 50%;
  background: radial-gradient(ellipse, rgba(var(--oc-rgb),.42), transparent 70%); filter: blur(7px); z-index: -1; pointer-events: none; }
