.nb-scope .orb:hover::before { animation-duration: 1.5s; opacity: 1; }
@keyframes orb-spin { to { transform: rotate(360deg); } }
.nb-scope .orb--glyph { display: inline-grid; place-items: center; font-size: 46px; color: #fff;
  text-shadow: 0 2px 10px rgba(0,0,0,.75), 0 0 22px rgba(var(--oc-rgb),.95); }
.nb-scope .orb--icon { width: 64px; height: 64px; font-size: 26px; }
.nb-scope .orb--icon::before { inset: -11px; padding: 2px; }
.nb-scope .orb--icon::after { bottom: -18px; height: 14px; }
.nb-scope .orb-ctx-card { border: 1px solid var(--line); border-radius: var(--r-lg); padding: 22px;
